// model/state.mjs -- state.json: saved searches, the session record, hidden groups and dead-channel memory. One part of Model.mjs (D-REL-5); its import and export lines are generated by split-model.mjs on the dev branch.
import {
  STATE_VERSION, SCOPE_RECENT, SCOPE_FAVORITES, MAX_HIDDEN_GROUPS, SEP
} from "./build.mjs"
import {
  str, asList, normalizeText, searchKey, tokenize, channelId
} from "./text.mjs"
import {
  primaryGroup, prepareChannels
} from "./channels.mjs"
import {
  matchRank, filterChannels, countFavorites, scopeSurface, channelsForScope,
  effectiveScope, launchScope
} from "./browse.mjs"
import {
  parseJsonObject
} from "./settings.mjs"
import {
  WALL_KEY
} from "./logos.mjs"
import {
  reconcileVerdict
} from "./player.mjs"
import {
  redactUrls, scrubUrls
} from "./privacy.mjs"
import {
  formatClock, formatCount, pluralChannels
} from "./epg.mjs"
import {
  guideSurface, footerStatus
} from "./view.mjs"
import {
  CACHE_LAYOUT, MAX_SOURCES, MAX_LABEL, MONTHS, isSourceKey, deriveLabel,
  uniqueLabel, sameDay, formatLastUsed
} from "./sources.mjs"
import {
  warnState, normalizeSourceRecord, activeKeyText, activeKeyOf,
  adoptActiveSource
} from "./source-records.mjs"

// ------------------------------------------------------------ state

// ---- saved searches (roadmap phase 4) --------------------------------------
//
// A saved search is a QUERY, not a list of ids, and the reason is measured: on
// the provider list 1 of 3,335 channel ids survives a password rotation and
// 3,335 of 3,335 names do. A term also picks up channels the provider adds
// later and works across bouquets that spell the same brand differently.
//
// The saved rows land in FAVOURITES rather than in a fifth scope. Favourites is
// already in scopeSurface, launchScope and the zap ring, so none of the three
// silent-failure paths a new scope id would touch is touched here.
//
// Bounds exist because the whole performance argument for this feature was
// stated "for ten terms", and that bound did not exist in the design. These
// follow the MAX_SOURCES 50 / MAX_LABEL 64 precedent.
var MAX_SAVED_SEARCHES = 20
var MAX_SAVED_TERMS = 8
var MAX_SAVED_QUERY = 64

// The membership predicate, deliberately NOT filterChannels.
//
// filterChannels is the RANKED, CAPPED display function: `pluto` returns rows
// 200 against total 2227, so a saved set built on it would have rows and a
// count that disagree by an order of magnitude. Worse, its slot arithmetic is
// `rank * 2 + (fav ? 0 : 1)`, so a saved set would silently REORDER when you
// favourited something inside it -- and these rows land in Favourites, so that
// is not hypothetical.
//
// It shares matchRank, so a saved search contains exactly the rows the search
// showed. What it does not share is the cap and the ordering.
function savedSearchTerms(query) {
  var toks = tokenize(str(query).slice(0, MAX_SAVED_QUERY))
  return toks.slice(0, MAX_SAVED_TERMS)
}

function savedSearchHit(channel, tokens) {
  if (!channel || tokens.length === 0) return false
  var key = typeof channel.searchKey === "string" ? channel.searchKey : searchKey(channel.name, channel.group)
  var nameKey = typeof channel.nameKey === "string" ? channel.nameKey : normalizeText(channel.name)
  return matchRank(key, tokens, nameKey) >= 0
}

// How many rows the terms AS TYPED would save. Shown in the confirmation so a
// bad term is visible in the moment: `baton rouge` shows 4 and `no tv` shows 75,
// because `tv` matches nearly everything.
function savedSearchCount(channels, query) {
  var tokens = savedSearchTerms(query)
  if (tokens.length === 0) return 0
  // Counted the way the rows are COLLECTED, by unique id: a playlist that
  // lists the same channel twice would otherwise have the confirmation promise
  // one more row than Favourites actually gains. Found by putting a real
  // duplicate in the fixture.
  var list = asList(channels)
  var seen = {}
  var n = 0
  for (var i = 0; i < list.length; i++) {
    if (!savedSearchHit(list[i], tokens)) continue
    var id = channelId(list[i])
    if (seen[id]) continue
    seen[id] = true
    n++
  }
  return n
}

// Every channel matched by ANY saved search, de-duplicated, in PLAYLIST ORDER.
//
// Playlist order and not match order: the rows join the user's starred
// channels in Favourites, and a list whose order depends on which saved search
// happened to match first would reshuffle whenever one was added or removed.
// First occurrence wins.
function savedSearchChannels(channels, saved) {
  var list = asList(channels)
  var terms = []
  var records = asList(saved)
  for (var s = 0; s < records.length && terms.length < MAX_SAVED_SEARCHES; s++) {
    var t = savedSearchTerms(records[s] && records[s].query)
    if (t.length > 0) terms.push(t)
  }
  if (terms.length === 0) return []
  var out = []
  var seen = {}
  for (var i = 0; i < list.length; i++) {
    var channel = list[i]
    if (!channel) continue
    for (var k = 0; k < terms.length; k++) {
      if (!savedSearchHit(channel, terms[k])) continue
      var id = channelId(channel)
      if (seen[id]) break
      seen[id] = true
      out.push(channel)
      break
    }
  }
  return out
}

// What the confirmation says. Composed here rather than in QML so a test can
// call it (rule 12), and so the COUNT is never optional: the whole reason this
// feature shows a number is that a term can quietly save far more than the
// user meant.
function savedSearchNotice(result, query, count) {
  var r = result || {}
  var terms = savedSearchTerms(query)
  var shown = terms.join(" ")
  if (!r.added) {
    if (r.reason === "duplicate") return "Already saved: " + shown
    if (r.reason === "full") return "Saved searches full (" + MAX_SAVED_SEARCHES + ")"
    return "Nothing to save"
  }
  return "Saved " + shown + SEP + formatCount(count) + (Number(count) === 1 ? " channel" : " channels")
}

// Why is this channel in Favourites? Returns "star", the saved search that put
// it there, or null.
//
// This exists because 0.7.6 shipped saved rows into Favourites with no way to
// take them out. `x` there calls the favourite toggle, and a saved row is not
// starred -- so the one key that looks like "remove this" ADDED a star, and
// pressing it again removed the star and left the row, because the search still
// matched. A dead end in both directions (D-SAVE-1).
function favoriteOrigin(state, channel) {
  var st = state || emptyState()
  if (!channel) return null
  if (isFavorite(st, channelId(channel))) return { kind: "star", query: "" }
  var saved = asList(st.savedSearches)
  for (var i = 0; i < saved.length; i++) {
    var terms = savedSearchTerms(saved[i] && saved[i].query)
    if (terms.length > 0 && savedSearchHit(channel, terms)) {
      return { kind: "saved", query: str(saved[i].query) }
    }
  }
  return null
}

// What `x` should say it did. Starred first, deliberately: a row that is BOTH
// starred and saved loses the star first, because the star is the narrower and
// more deliberate of the two and removing the search would take other rows with
// it. A second `x` then removes the search.
function favoriteRemovalNotice(origin, count) {
  var o = origin || {}
  if (o.kind === "star") return "Removed from Favorites"
  if (o.kind === "saved") {
    return "Forgot " + savedSearchTerms(o.query).join(" ") + SEP +
      formatCount(count) + (Number(count) === 1 ? " channel" : " channels")
  }
  return ""
}

// M3-01: what the footer says after `x` hid or unhid a group. `hidden` is
// the state AFTER the press as the service reports it (null: refused at the
// cap). The group name is playlist text, so it goes through scrubUrls like
// every other sink (rule 5). Says where the group went, because a user who
// hid 117 rows by one keypress deserves to be told how to get them back.
// Where the notice sends the user depends on what the view actually draws.
// `view` is { wall, narrow } -- the same two facts guideSurface uses to
// decide showColumn, which is `has && !narrow && !wall`.
//
//   column drawn   "under HIDDEN in the column"
//   the wall       Ctrl+G, the key back to the view that has the column
//   a narrow card  h/l, which still rings the scopes (including the hidden
//                  entries) even though the column is not drawn
//
// The first repair keyed on the wall alone, which was the half of the
// premise its author had looked at: a narrow card has no column either and
// was still being told to look at one. Both were found by a preflight, one
// pass apart, which is the argument for keying on the fact rather than on
// the view that made you notice it.
function hideNotice(hidden, group, count, view) {
  var v = view || {}
  var name = scrubUrls(str(group))
  var n = formatCount(count) + (Number(count) === 1 ? " channel" : " channels")
  if (hidden === null || hidden === undefined) return "Cannot hide more groups" + SEP + MAX_HIDDEN_GROUPS + " is the most"
  if (hidden !== true) return "Showing " + name + SEP + n
  // Four views, not three: a NARROW wall leads to a narrow list, which has
  // no column either, so naming Ctrl+G alone would send that user to a
  // second view without the thing they were told to look at. Found one pass
  // after the narrow case itself, which is what happens when a rule is
  // extended by the example that prompted it rather than by its own terms.
  var where = "under HIDDEN in the column"
  if (v.wall === true) where = v.narrow === true ? WALL_KEY + ", then h/l to reach it" : WALL_KEY + " for the list to unhide"
  else if (v.narrow === true) where = "h/l to reach it under HIDDEN"
  return "Hid " + name + SEP + n + SEP + where
}

// The group column entry's accessible name (UX 7.1). A hidden entry says
// so, because the dimming that tells a sighted user is not on the bus.
function scopeEntryAccessibleName(entry) {
  var e = entry || {}
  var label = str(e.label)
  if (e.kind === "header") return label
  var name = label + ", " + pluralChannels(e.count)
  return e.kind === "hidden" ? name + ", hidden" : name
}

// THE ONE RULE FOR BOTH SAVED-SEARCH CONFIRMATIONS: the number is the change
// in Favourites ROWS -- what saving adds, what forgetting takes away. Neither
// derives it; each asks channelsForScope for the rows with and without the
// search and subtracts, so there is nothing to keep in step.
//
// The number the user sees before the press is the scope column's
// "Favorites N" (countFavorites), which IS on screen at that moment. The
// saved-search FOOTER line is not: footerStatus returns the transient eight
// rungs above it, so the notice replaces that line rather than sitting
// beside it. Three documents and two shipped comments said "the footer
// beside it", which was a plausible reconstruction nobody checked against
// footerStatus -- the divergence was real, the staging was invented.
//
// It took four goes. The count was wrong in savedSearchFooter (D-SAVE-2),
// then in countFavorites, then `savedSearchCountVisible` was written for the
// two guide sites those repairs had left behind (D-SAVE-4, which fixed the
// hidden-group half and not the star half), then D-SAVE-6 gave the FORGET
// site row arithmetic and left the SAVE site on the match count -- so the two
// confirmations, which had at least agreed with each other, began reporting
// different numbers for the same search. That is why both live here now and
// why `savedSearchCountVisible` is gone rather than kept for one caller: a
// helper whose name promises the Favourites effect and does not deliver it is
// what the next person reaches for.
//
// A match count is NOT this number. A channel the user already starred is
// matched by the search and stays in Favourites either way, so it is neither
// an arrival nor a departure.
function savedSearchRows(channels, state) {
  return channelsForScope(channels, SCOPE_FAVORITES, state || emptyState()).length
}

// Rows Favourites GAINS when this search is saved. 0 when the search is
// refused (already saved, at the cap, empty) or when every match is starred.
function savedSearchArrivals(channels, state, query, at) {
  var st = state || emptyState()
  var result = withSavedSearch(st, query, Math.floor(Number(at) || 0))
  if (!result || result.added !== true) return 0
  return Math.max(0, savedSearchRows(channels, result.state) - savedSearchRows(channels, st))
}

// Rows Favourites LOSES when this search is forgotten.
function savedSearchDepartures(channels, state, query) {
  var st = state || emptyState()
  return Math.max(0, savedSearchRows(channels, st) - savedSearchRows(channels, withoutSavedSearch(st, query)))
}

// How many Favourites rows come from saved searches rather than stars. Shown in
// the footer so the list is explicable: otherwise Favourites fills with
// channels the user never starred and nothing says why.
function savedSearchFooter(state, channels) {
  var st = state || emptyState()
  var saved = asList(st.savedSearches)
  if (saved.length === 0) return ""
  // D-SAVE-2's rule, and it took two goes to obey it. The first repair
  // filtered this expression the way channelsForScope filters, which fixed
  // the hidden-group divergence and left a second one standing: the rows
  // de-duplicate the saved matches against the STARS, and a re-derived count
  // does not, so a channel the user had both starred and matched was counted
  // as a saved row although it is in the list as a star. Two implementations
  // agreeing about one input is not one call. This is one call: count the
  // rows channelsForScope actually returns, and subtract the stars among
  // them -- which is exactly the shape countFavorites has.
  var rows = 0
  var favRows = channelsForScope(channels, SCOPE_FAVORITES, st)
  var starred = {}
  for (var f = 0; f < st.favorites.length; f++) starred[str(st.favorites[f])] = true
  for (var r = 0; r < favRows.length; r++) if (starred[channelId(favRows[r])] !== true) rows++
  return formatCount(saved.length) + (saved.length === 1 ? " saved search" : " saved searches") +
    SEP + formatCount(rows) + (rows === 1 ? " channel" : " channels")
}

// Add a saved search, or report why not. Pure: returns the next state and a
// verdict, never mutates. The verdict is what the confirmation says, so a
// refusal is visible in the moment rather than silently doing nothing.
function withSavedSearch(state, query, at) {
  var st = state || emptyState()
  var terms = savedSearchTerms(query)
  var list = asList(st.savedSearches).slice()
  if (terms.length === 0) return { state: st, added: false, reason: "empty" }
  var sig = terms.join(" ")
  for (var i = 0; i < list.length; i++) {
    if (savedSearchTerms(list[i] && list[i].query).join(" ") === sig) {
      return { state: st, added: false, reason: "duplicate" }
    }
  }
  if (list.length >= MAX_SAVED_SEARCHES) return { state: st, added: false, reason: "full" }
  var rec = savedSearchRecord({ query: query, at: at })
  if (!rec) return { state: st, added: false, reason: "empty" }
  list.push(rec)
  return { state: cloneState(st, { savedSearches: list }), added: true, reason: "" }
}

// Remove one, matched on the FOLDED terms so the caller does not have to know
// how the stored string was spelled.
function withoutSavedSearch(state, query) {
  var st = state || emptyState()
  var sig = savedSearchTerms(query).join(" ")
  if (sig === "") return st
  var kept = asList(st.savedSearches).filter(function (r) {
    return savedSearchTerms(r && r.query).join(" ") !== sig
  })
  return cloneState(st, { savedSearches: kept })
}

// One stored record. A query that tokenizes to nothing is not a saved search.
function savedSearchRecord(entry) {
  if (!entry || typeof entry !== "object") return null
  var query = str(entry.query).slice(0, MAX_SAVED_QUERY)
  if (savedSearchTerms(query).length === 0) return null
  return { query: query, at: Math.trunc(Number(entry.at)) || 0 }
}

function emptyState() {
  return { version: STATE_VERSION, cacheLayout: 0, favorites: [], recents: [], lastPlayed: null, session: null, sources: [], savedSearches: [], hiddenGroups: [], activeKey: "" }
}

// D-SINK-19 round 11, R21a. THE MIGRATION MARKER.
//
// The bar entry's `playlistUrl` and `epgUrl` are read as INPUT exactly once
// per install: by the migration of a state file written before D-SINK-19
// (0.13.x named the active source by the URL on the entry). The migration
// adopts what the entry carries (Model.adoptActiveSource with `migrating`)
// and sets this boolean in the SAME state write, and from the moment a state
// write carrying it has LANDED nothing on the entry is an input again: a
// value found there is refused, reported once and stripped (R21b). The
// product owner dropped the `omarchy bar set` URL route on 2026-10-13 after
// ten repair rounds of state built to tell a CLI input from the host's
// stale echo of one did not converge.
//
// Present only when true, so a state that has not migrated serializes as it
// did before; additive at STATE_VERSION 2 on the activeKey precedent, and
// taught to the helper's normalize_state on the same day and the same shared
// fixture (the shared state-keys fixture, dev branch). An OLDER build drops
// it with every other key it does not know, and that is the downgrade the
// ruling names: 0.13.6 writes the active URL back onto the entry and keeps
// no marker, so a re-upgrade migrates again, over what 0.13.6 wrote.
// Exactly `true`: a string "true" or a 1 is not a marker (activeKeyText's
// lesson, the coercion that reads one way here and another in the helper).
function entryMigratedOf(state) {
  return !!(state && typeof state === "object" && state.entryMigrated === true)
}

// The state with the marker set; the SAME object when it already carries it,
// so a caller's "did the state move" stays an identity test.
function withEntryMigrated(state) {
  var st = state || emptyState()
  if (entryMigratedOf(st)) return st
  return cloneState(st, { entryMigrated: true })
}

// One `{id, name, at}` record: the shape a `recents` entry, `lastPlayed`
// and `session` all share (python mirror: `normalize_played`). A value
// without an `id` is dropped, which is also how a state file written
// before the key existed reads its missing `session` as null.
function playedRecord(entry) {
  if (!entry || typeof entry !== "object" || !entry.id) return null
  // Math.trunc, not Math.floor: python's int() truncates toward zero, and the
  // shared fixture pins the two readers to the same answer on the same bytes.
  return { id: String(entry.id), name: str(entry.name), at: Math.trunc(Number(entry.at)) || 0 }
}

// Every reducer builds its result here so `sources` and `cacheLayout` are
// carried through favorites / recents changes (ARCHITECTURE-SOURCES 2.1).
function cloneState(state, patch) {
  var st = state || emptyState()
  var out = {
    version: STATE_VERSION,
    cacheLayout: Number(st.cacheLayout) === CACHE_LAYOUT ? CACHE_LAYOUT : 0,
    favorites: asList(st.favorites).slice(),
    recents: asList(st.recents).slice(),
    lastPlayed: st.lastPlayed || null,
    session: st.session || null,
    sources: asList(st.sources).slice(),
    // A THIRD whitelist, and it erases exactly like the other two did. This
    // rebuilds the document field by field, so a key it does not name is gone
    // -- and Service.qml clones state to write a source record, which would
    // have wiped every saved search on the next source edit. The roadmap
    // warned about two whitelists; there are three.
    savedSearches: asList(st.savedSearches).slice(),
    // M3-01. The fourth key this whitelist had to be taught, and the test
    // that proves it is the same shape as the savedSearches one: a state
    // that carries it goes through every reducer and comes out with it.
    hiddenGroups: asList(st.hiddenGroups).slice(),
    // D-SINK-19. The FIFTH, and the one whose loss is worst: it is the only
    // record of which source is active, so a reducer that dropped it would
    // un-configure the plugin on the next favourite toggle. Additive at
    // STATE_VERSION 2 exactly like hiddenGroups -- a file without it reads
    // as "", an older build drops it, the version does not move.
    //
    // Through activeKeyText and NOT str(): this is the sibling of the
    // activeKeyText fix that the first round missed (rule 15). str() coerces
    // the number 12345678 and the list ["d990c2e4"] into values that sit
    // inside the key grammar, and every reducer passes through here, so a raw
    // state object handed to one would have come out "configured" on this
    // side and unconfigured on the helper's (normalize_active_key requires a
    // string). One reader, one rule, the same answer as parseState.
    activeKey: activeKeyText(st.activeKey)
  }
  // D-SINK-19 round 11, R21a: the SIXTH key this whitelist is taught, on
  // the day it is added. Carried only when it is exactly true, so a state
  // that has not migrated clones to exactly the shape it had before.
  if (st.entryMigrated === true) out.entryMigrated = true
  var p = patch || {}
  for (var key in p) if (key !== "version") out[key] = p[key]
  return out
}

function withCacheLayout(state, layout) {
  return cloneState(state, { cacheLayout: Number(layout) === CACHE_LAYOUT ? CACHE_LAYOUT : 0 })
}

// v1 (no `sources`) and v2 text both yield a v2 object (ARCHITECTURE-SOURCES
// 2.2); records failing the field rules are dropped, duplicate `url` or
// `key` keeps the first, the array is capped at MAX_SOURCES.
function parseState(text) {
  var state = emptyState()
  var parsed = parseJsonObject(text)
  if (!parsed) return state
  state.cacheLayout = Number(parsed.cacheLayout) === CACHE_LAYOUT ? CACHE_LAYOUT : 0
  var srcs = asList(parsed.sources)
  var seenUrl = {}
  var seenKey = {}
  for (var s = 0; s < srcs.length && state.sources.length < MAX_SOURCES; s++) {
    var rec = normalizeSourceRecord(srcs[s])
    if (!rec) {
      // Logged by key (D-SRC-09); a record without a usable key is silent.
      var badKey = srcs[s] && typeof srcs[s] === "object" ? str(srcs[s].key) : ""
      if (isSourceKey(badKey)) warnState("dropped source " + badKey + " (invalid url)")
      continue
    }
    if (seenUrl[rec.url] || seenKey[rec.key]) continue
    // D-SINK-17, the half the first fix missed. `deriveLabel`'s output is
    // STORED, so repairing the derivation does nothing for a record written
    // before the repair: an install that added
    // `https://u@er:pass@host.example/list.m3u` on 0.13.1 or earlier holds
    // `er:pass@host.example` in state.json as its label, and that label is a
    // WIDER sink than the host beside it -- the guide header, the switched
    // toast, the IPC status payload and the helper's own source listing all
    // carry it, and `redactUrls` cannot help because a bare `er:pass@host`
    // has no `://` for it to find. So a label the USER did not choose is
    // re-derived on every load. It is deterministic, so an unaffected record
    // gets the same string it already had and nothing moves; an affected one
    // heals itself the first time the file is read. `labelCustom` is the
    // whole of the distinction: a name the user typed is theirs, and this
    // never touches it.
    //
    // Re-derived HERE rather than in normalizeSourceRecord, because
    // uniqueness is a property of the list and not of a record: two sources
    // on one host must not both come back as that host.
    if (rec.labelCustom !== true) rec.label = uniqueLabel(deriveLabel(rec.url, rec.kind), state.sources)
    seenUrl[rec.url] = true
    seenKey[rec.key] = true
    state.sources.push(rec)
  }
  var favs = asList(parsed.favorites)
  if (favs.length > 0) {
    for (var i = 0; i < favs.length; i++) {
      var id = str(favs[i])
      if (id !== "" && state.favorites.indexOf(id) === -1) state.favorites.push(id)
    }
  }
  // M3-01. Additive and optional like savedSearches below: a file without
  // it reads as [], an older build drops it, STATE_VERSION stays 2.
  state.hiddenGroups = hiddenGroupList(parsed.hiddenGroups)
  // D-SINK-19. Which source is active, by KEY. Additive at version 2 on the
  // same precedent as hiddenGroups and savedSearches. A value that is not a
  // key reads as "" rather than failing; a key naming no record is kept here
  // and resolved to "" by activeKeyOf, because dropping it at parse time
  // would hide the case the migration has to decide about.
  state.activeKey = activeKeyText(parsed.activeKey)
  // D-SINK-19 round 11, R21a: the migration marker. Absent unless exactly
  // true (entryMigratedOf).
  if (parsed.entryMigrated === true) state.entryMigrated = true
  var recs = asList(parsed.recents)
  for (var r = 0; r < recs.length; r++) {
    var entry = playedRecord(recs[r])
    if (entry) state.recents.push(entry)
  }
  state.lastPlayed = playedRecord(parsed.lastPlayed)
  // Saved searches. Additive and optional, on the same precedent as `session`
  // below: both readers whitelist the keys they know, so a file without this
  // reads as [] and an older build drops it rather than failing. De-duplicated
  // on the folded terms, not on the raw string, so `BBC ` and `bbc` are one
  // saved search and not two.
  var saves = asList(parsed.savedSearches)
  var seenTerms = {}
  for (var v = 0; v < saves.length && state.savedSearches.length < MAX_SAVED_SEARCHES; v++) {
    var rec2 = savedSearchRecord(saves[v])
    if (!rec2) continue
    var sig = savedSearchTerms(rec2.query).join(" ")
    if (seenTerms[sig]) continue
    seenTerms[sig] = true
    state.savedSearches.push(rec2)
  }
  // The detached player's session record (ARCHITECTURE-PLAYER.md 4.6 and
  // section 8): optional, nullable, and no version bump - STATE_VERSION
  // stays 2 because both readers whitelist the keys they know, so a file
  // without it reads as null and a v0.2.0 build simply drops it.
  state.session = playedRecord(parsed.session)
  return state
}

// pushRecent()'s `{id, name, at}` form, for replaying a play that was
// recorded before state.json landed (stateOnLoad).
function pushPlayedRecord(recents, played, max) {
  var rec = playedRecord(played)
  var cap = max > 0 ? Math.floor(max) : 10
  var out = []
  if (rec) out.push(rec)
  var list = asList(recents)
  for (var i = 0; i < list.length && out.length < cap; i++) {
    if (list[i] && (!rec || list[i].id !== rec.id)) out.push(list[i])
  }
  return out
}

// ARCHITECTURE-PLAYER.md section 15's startup race, measured at 14 losses in
// 30 trials, and the other half of the consumption rule above.
//
// state.json is read asynchronously while a play can be issued immediately,
// so the text that arrives is a snapshot of the file from BEFORE anything
// this shell did. Applying it wholesale is the whole race: the session
// record the play had just written is gone, and with it the only evidence
// PO-3 has that the channel died unattended.
//
// The file is the base - it carries favorites, sources and the recents of
// every previous login, none of which this shell can reconstruct. What is
// replayed on top is exactly one thing, the play this shell recorded while
// the read was in flight, because before the first load `userState` IS the
// empty default plus that write, so a `session` there can only be ours.
// `savePending` extends the same reasoning past the first load: a save this
// shell has queued but not yet been allowed to make (saveState()'s dirsReady
// gate) means the file on disk is again older than memory.
//
// Whether a replayed record then SURVIVES is not decided here: it goes to
// sessionAfterOutcome() like every other answer about the record, so there
// stays exactly one place that retires one.
function stateOnLoad(loaded, current, context) {
  var base = loaded || emptyState()
  var ctx = context || {}
  var newer = ctx.loadedBefore !== true || ctx.savePending === true
  var mine = newer ? playedRecord(current && current.session) : null
  if (!mine) return { state: base, replayed: false, write: false }
  var next = cloneState(base, {
    recents: pushPlayedRecord(base.recents, mine, ctx.maxRecents),
    lastPlayed: mine,
    session: mine
  })
  return { state: next, replayed: true, write: next !== base }
}

function isFavorite(state, id) {
  return !!(state && asList(state.favorites).indexOf(str(id)) !== -1)
}

// Returns a new favorites array; never mutates the input.
function toggleFavorite(favorites, id) {
  var key = str(id)
  var list = asList(favorites).slice()
  if (key === "") return list
  var at = list.indexOf(key)
  if (at === -1) list.push(key)
  else list.splice(at, 1)
  return list
}

// Newest first, de-duplicated by id, capped at `max`. Returns a new array.
function pushRecent(recents, channel, max, nowSec) {
  var id = channelId(channel)
  var cap = max > 0 ? Math.floor(max) : 10
  var out = []
  if (id !== "") out.push({ id: id, name: str(channel.name), at: Math.floor(Number(nowSec) || 0) })
  var list = asList(recents)
  for (var i = 0; i < list.length && out.length < cap; i++) {
    if (list[i] && list[i].id !== id) out.push(list[i])
  }
  return out
}

// New state object after the play command (R5: recorded on the command, not
// on playback success). `lastPlayed` and `session` are the same record
// under two different lifetimes: `lastPlayed` is the Recents memory and
// survives everything, `session` is "what the player was last asked to
// play" and is cleared the moment the player stops or ends cleanly
// (ARCHITECTURE-PLAYER.md section 8). A record left behind therefore means
// the player died with no shell attached to notice, which is the one thing
// a reattach needs in order to mark that channel failed in the guide
// instead of raising a toast minutes late (ruling PO-3). It carries a
// channel id, a display name and a clock - never a URL, because a display
// name is never a URL (prepareChannels) and the id is a tvg-id or a hash.
function recordPlayed(state, channel, max, nowSec) {
  var st = state || emptyState()
  var id = channelId(channel)
  var played = id === "" ? null : { id: id, name: str(channel.name), at: Math.floor(Number(nowSec) || 0) }
  return cloneState(st, {
    recents: pushRecent(st.recents, channel, max, nowSec),
    lastPlayed: played || st.lastPlayed || null,
    session: played || st.session || null
  })
}

// The player stopped, ended cleanly, or its channel has just been marked
// failed on reattach: the session record has done its job. Returns the SAME
// object when there is nothing to clear, so a caller can skip the write.
function clearSession(state) {
  var st = state || emptyState()
  if (!st.session) return st
  return cloneState(st, { session: null })
}

// What the player was last asked to play, or null. Normalizing on the way
// out means a hand-edited or truncated record can never reach the guide as
// half a channel.
function stateSession(state) {
  return state ? playedRecord(state.session) : null
}

// Ruling PO-3, the whole decision. A `player probe` that found nothing
// running, paired with a session record still in state.json, is the evidence
// that the channel the record names died with no shell attached to notice:
// mark it failed in the guide, silently, and clear the record. A toast for
// something that stopped minutes ago, possibly on another login, is noise.
//
// The answer depends on whether the state file has landed yet, because the
// two arrive in either order: the probe fires from Component.onCompleted and
// answers in about 130 ms, while state.json arrives whenever its FileView
// loads. Deciding on a state that has not loaded would read the empty
// default - losing the mark, and, if the caller wrote that result back,
// putting an empty state over the user's file. So an unloaded state yields
// `pending`, which the caller re-runs from its state handler, and never a
// write.
//
// `state` is returned unchanged (the same object) whenever there is nothing
// to clear, so `write` is also "the state actually changed".
function deadSessionVerdict(state, stateLoaded, failed, clock) {
  var marks = failed && typeof failed === "object" ? failed : {}
  if (stateLoaded !== true) return { pending: true, mark: false, id: "", name: "", failed: marks, state: state, write: false }
  var session = stateSession(state)
  if (!session) return { pending: false, mark: false, id: "", name: "", failed: marks, state: state, write: false }
  var cleared = clearSession(state)
  return {
    pending: false,
    mark: true,
    id: session.id,
    name: session.name,
    failed: withFailed(marks, session.id, clock),
    state: cleared,
    write: cleared !== state
  }
}

// ------------------------------------------- the session record's lifetime
//
// The other half of PO-3, and the half that decides whether the mark above is
// ever raised twice for the same event.
//
// recordPlayed() writes the record on the play command; deadSessionVerdict()
// is its ONLY reader, and it reads a SURVIVING record as proof that the
// channel died with no shell attached to notice. So the rule is about the
// witness, not about the failure: a record must never outlive the shell that
// saw how the play ended. Whether the user got a toast and a red row, "mpv
// not found", a clean end that PO-4 keeps silent, or their own stop makes no
// difference - they have had whatever they were going to get, and a mark on
// the next reattach would be a second verdict on an event they already dealt
// with. A record therefore survives exactly one thing: a player that is still
// running or still on its way.
//
// This lives here rather than as a condition per branch in Service.qml
// because that is how the reported defect happened: three of the terminal
// branches wrote the clear and three did not, and nothing outside a running
// shell could call the rule to find out (engineering rule 11 (dev branch), 12).

// Every answer Service.qml can get about the player it asked for, and whether
// the player survives it. `false` is "gone, and nothing is bringing it back".
var PLAYER_OUTCOME_SURVIVES = {
  superseded: true,     // a later intent won the lock; that intent owns the record
  retrying: true,       // busy / no_socket / ipc_error, the backoff is armed
  relaunching: true,    // the health verdict's one automatic relaunch (4.8)
  respawning: true,     // the helper is mid ladder-and-respawn for this very intent (4.9)
  attached: true,       // the first load failed but the socket is live: its EOF is next
  loaded: true,         // not a player answer: state.json arriving (see `consumed` below)
  stopped: false,       // the user stopped it, or a detached stop was confirmed (4.9)
  ended: false,         // socket EOF with no relaunch coming (4.8 signal 3)
  foreign: false,       // a player this shell could not identify, laddered down (4.5)
  unverified: false,    // D-SINK-16: a player that could not be made to verify
                        // the stream's certificate, laddered down rather than
                        // handed another credentialed URL
  failed: false,        // `player start` / `restart` / the first load failed for good
  mpvMissing: false,    // the player program is not installed
  marked: false,        // PO-3's red row has been raised on this record: it is spent
  abandoned: false      // the channel left the playlist before the relaunch could run
}

// The vocabulary, so a test can pin the set instead of trusting a call site's
// spelling: an outcome this does not name is inert (see sessionAfterOutcome).
var PLAYER_OUTCOMES = Object.keys(PLAYER_OUTCOME_SURVIVES)

// The session record after one player outcome. Returns the SAME state object
// whenever nothing changed, so a caller can skip the write - the contract
// clearSession() and deadSessionVerdict() already keep.
//
// `deadPending` is the caller's deferred-PO-3 flag (deadSessionVerdict's
// `pending`: a probe found no player before state.json had landed, so the
// mark is owed once it does). A terminal outcome drops it, because the user
// has now seen the end of this play and the deferred mark would be the
// second word on the same event; a NON-terminal one must leave it alone, or
// a `busy` retry racing the startup probe silently eats a red row that a
// genuine unattended death had earned. It is answered here rather than in
// the component so that something can call the rule.
//
// An outcome this does not know is inert rather than clearing: a misspelled
// call site then costs at worst one stale mark on the next reattach, never a
// silently dropped one, and the vocabulary check in the tests catches it
// before either happens.
function sessionAfterOutcome(state, outcome, deadPending, consumed) {
  var st = state || emptyState()
  var key = str(outcome)
  var known = PLAYER_OUTCOME_SURVIVES.hasOwnProperty(key)
  var terminal = known && PLAYER_OUTCOME_SURVIVES[key] !== true
  // Consumption is one-way, and it is the half the twelve routed branches
  // left open. They retire the record in MEMORY; whether that reaches disk
  // depends on `dirsReady` and on which of state.json's own loads wins the
  // race. When the write loses, the file still carries the record, the next
  // load puts it straight back into memory, and the following shell start
  // marks the same channel red a second time for a failure the user has
  // already been shown - the reported defect, 2 runs in 3. So the answer is
  // not "clear it once" but "a consumed record never comes back": every
  // later call over the same in-memory state, `loaded` included, clears it
  // again until a write finally lands. Only a new play (recordPlayed) opens
  // a fresh record, and the caller drops the flag there.
  var spent = consumed === true || terminal
  var next = spent ? clearSession(st) : st
  return {
    outcome: key,
    known: known,
    terminal: terminal,
    consumed: spent,
    pending: terminal ? false : deadPending === true,
    state: next,
    write: next !== st
  }
}

function withFavorites(state, favorites) {
  return cloneState(state, { favorites: asList(favorites).slice() })
}

// ---- hidden groups (M3-01, PLAN-M3 section 1)
//
// A hidden group leaves browsing -- All, GROUPS, search from All, saved
// searches, the wall, the ring -- and nothing else. A star, a recent and a
// channel number are things the user did on purpose and keep working
// (decision 1). The list is group NAMES, global across sources (decision 4).

// The one reader both languages agree on (python: normalize_hidden_groups):
// strings only, trimmed, non-empty, first occurrence wins, capped.
function hiddenGroupList(raw) {
  var list = asList(raw)
  var out = []
  var seen = {}
  for (var i = 0; i < list.length && out.length < MAX_HIDDEN_GROUPS; i++) {
    if (typeof list[i] !== "string") continue
    var name = list[i].replace(/^\s+|\s+$/g, "")
    if (name === "" || seen[name] === true) continue
    seen[name] = true
    out.push(name)
  }
  return out
}

function hiddenGroupSet(state) {
  var st = state || emptyState()
  var list = asList(st.hiddenGroups)
  var out = {}
  for (var i = 0; i < list.length; i++) if (typeof list[i] === "string" && list[i] !== "") out[list[i]] = true
  return out
}

function isGroupHidden(state, name) {
  var key = str(name)
  return key !== "" && hiddenGroupSet(state)[key] === true
}

// Hide when shown, show when hidden. An unknown or empty name is a no-op
// that returns the SAME state, so a caller comparing by reference can tell
// "nothing changed" from "changed" without a second call.
function toggleHiddenGroup(state, name) {
  var st = state || emptyState()
  var key = str(name).replace(/^\s+|\s+$/g, "")
  if (key === "") return st
  var list = hiddenGroupList(st.hiddenGroups)
  var at = list.indexOf(key)
  if (at !== -1) list.splice(at, 1)
  else if (list.length >= MAX_HIDDEN_GROUPS) return st
  else list.push(key)
  return cloneState(st, { hiddenGroups: list })
}

// The channels a user browses: the list minus every hidden group. With
// nothing hidden this is the SAME array, not a copy, because
// channelsForScope(all) used to return the list itself and callers may
// compare by identity; a filter that always copied would change that
// silently. Costs one primaryGroup per channel only when something is
// hidden -- measured at 10,000 channels in QA-RESULTS M3-01.
function browsableChannels(channels, state) {
  var list = asList(channels)
  var hidden = hiddenGroupSet(state)
  var any = false
  for (var k in hidden) { any = true; break }
  if (!any) return list
  var out = []
  for (var i = 0; i < list.length; i++) {
    if (!list[i]) continue
    if (hidden[primaryGroup(list[i])] !== true) out.push(list[i])
  }
  return out
}

// What `x` does on the cursor row (UX 3.1, extended by PLAN-M3 decision 3).
// One table: the key handler dispatches on `action` and the footer derives
// its verb from the same call, so the hint cannot promise a removal the
// handler does not make. Recent and Favorites keep their existing meaning;
// everywhere else the unit of removal is the row's group.
function hideAction(opts) {
  var o = opts || {}
  var scope = effectiveScope(o.scopeId, o.query)
  if (scope === SCOPE_RECENT) return { action: "recent", group: "" }
  if (scope === SCOPE_FAVORITES) return { action: "favorite", group: "" }
  if (!o.channel) return { action: "none", group: "" }
  var group = primaryGroup(o.channel)
  return { action: isGroupHidden(o.state, group) ? "unhide" : "hide", group: group }
}

// The footer's word for `x`, from the same table. "" means no hint.
function hideVerb(opts) {
  var act = hideAction(opts).action
  if (act === "hide") return "hide group"
  if (act === "unhide") return "unhide"
  return ""
}

function removeRecent(state, id) {
  var st = state || emptyState()
  var key = str(id)
  var recents = []
  var list = asList(st.recents)
  for (var i = 0; i < list.length; i++) if (list[i] && list[i].id !== key) recents.push(list[i])
  return cloneState(st, { recents: recents })
}

// Trim recents to the configured cap (settings can shrink after the fact).
function trimRecents(state, max) {
  var st = state || emptyState()
  var cap = max > 0 ? Math.floor(max) : 10
  var list = asList(st.recents)
  if (list.length <= cap) return st
  return cloneState(st, { recents: list.slice(0, cap) })
}

// Session-only failure memory (R11): { id: "HH:MM" }. New objects every time.
// ---- dead-channel memory (PO 2026-09-24, amending R8 / R11 / UX ruling 9)
//
// A failure mark now SURVIVES a restart. Three decisions decide the rest, and
// each of them is the answer to something a design review broke:
//
// 1. IT IS NOT IN state.json. Channel ids are global across sources
//    (ARCHITECTURE-SOURCES D14), so a state-level map would mark a DIFFERENT
//    provider's working channel with a failure earned on this one. And a map
//    keyed by channel id falls inside D-ID-1's id-rotation blast radius --
//    which that defect's row records as excluded precisely BECAUSE this was
//    session-only. Storing it per source keeps that exclusion true, for a
//    better reason: the marks live with the cache whose ids they name.
//
// 2. IT IS AN ARRAY, newest first, not a map. The savedSearches precedent
//    chose an array for deterministic eviction order, and a `{id: at}` object
//    has no iteration contract to evict by across two languages.
//
// 3. THE VALUE IS AN EPOCH, not the "HH:MM" it used to be. A display string is
//    meaningless the day after it is written. Rendering is `failedNoticeAt`,
//    below, which says the clock for today and the date for anything older so
//    the row never implies a week-old observation is current.
//
// A mark is dropped four ways: the channel plays, it ages out, its id leaves
// the playlist, or its source is removed. `prunedFailed` does the middle two;
// the rest is the existing withoutFailed / failedAfterHealthy path.
var MAX_FAILED = 300
var FAILED_TTL_SEC = 14 * 24 * 3600

// Read a failed.json document into the in-memory list. Deliberately takes no
// clock: a parser that ages entries out is clock-dependent, which makes the
// shared fixtures untestable. Aging is `prunedFailed`, at a named call site.
function parseFailed(text) {
  var doc = parseJsonObject(text)
  if (!doc) return []
  return normalizeFailed(doc.failed)
}

function normalizeFailed(list) {
  var rows = asList(list)
  var out = []
  var seen = {}
  for (var i = 0; i < rows.length; i++) {
    var r = rows[i]
    if (!r || typeof r !== "object") continue
    var id = str(r.id)
    var at = Math.floor(Number(r.at))
    if (id === "" || !isFinite(at) || at <= 0) continue
    if (seen[id] === true) continue
    seen[id] = true
    out.push({ id: id, at: at })
    if (out.length >= MAX_FAILED) break
  }
  return out
}

// The two drops that need context: too old, and no longer in the playlist.
//
// `knownIds` is the id set of the CURRENT channels.json. Dropping a mark whose
// channel is gone is what makes this self-healing: an id rotation, a provider
// reshuffle and a removed channel all produce marks that name nothing, and all
// three are cleaned up here rather than by a migration nobody would maintain.
// Passing no set at all skips that half, so a caller without channels loaded
// yet cannot wipe the file.
function prunedFailed(list, nowSec, knownIds) {
  var now = Math.floor(Number(nowSec) || 0)
  var rows = normalizeFailed(list)
  var out = []
  for (var i = 0; i < rows.length; i++) {
    if (now > 0 && rows[i].at < now - FAILED_TTL_SEC) continue
    if (knownIds && knownIds[rows[i].id] !== true) continue
    out.push(rows[i])
  }
  return out
}

// { id: true } for prunedFailed, from whatever channel list the caller holds.
function knownIdSet(channels) {
  var list = asList(channels)
  var out = {}
  for (var i = 0; i < list.length; i++) {
    var id = channelId(list[i])
    if (id !== "") out[id] = true
  }
  return out
}

// The list as the guide wants it: { id: at } for O(1) row lookup. The ROW
// still asks by id, so this is the shape the render path keeps.
function failedIndex(list) {
  var rows = normalizeFailed(list)
  var out = {}
  for (var i = 0; i < rows.length; i++) out[rows[i].id] = rows[i].at
  return out
}

function failedDocument(list) {
  return { version: 1, failed: normalizeFailed(list) }
}

// What the row says. `Failed 21:05` for today, `Failed 8 Sep` for older, and
// the year when it is not this one -- the formatLastUsed idiom, so the guide
// has one voice for "a time in the past".
//
// Never "Dead" or "Broken": the mark is a record of one observation, not a
// claim about the channel now, and a week-old failure said in the present
// tense would be a lie the user cannot check.
function failedWhen(atSec, nowSec) {
  var at = Math.floor(Number(atSec) || 0)
  if (at <= 0) return ""
  var d = new Date(at * 1000)
  var now = Number(nowSec) > 0 ? new Date(Number(nowSec) * 1000) : new Date()
  if (sameDay(d, now)) return formatClock(at)
  var yesterday = new Date(now.getTime())
  yesterday.setDate(yesterday.getDate() - 1)
  if (sameDay(d, yesterday)) return "yesterday"
  var text = d.getDate() + " " + MONTHS[d.getMonth()]
  if (d.getFullYear() !== now.getFullYear()) text += " " + d.getFullYear()
  return text
}

// PO 2026-09-24: the value is an EPOCH now, and it is stored as the NUMBER it
// is. It used to be str()'d, which was right while the value was the display
// string "HH:MM" and is wrong for a stamp -- `failedIndex` produces numbers
// from the file, so a str() here would make the same map hold numbers from
// disk and strings from this turn, and the two would format identically right
// up until something compared them.
function withFailed(failed, id, at) {
  var out = {}
  var src = failed && typeof failed === "object" ? failed : {}
  for (var k in src) out[k] = src[k]
  if (str(id) !== "") out[str(id)] = typeof at === "number" ? at : str(at)
  return out
}

// D-PLY-14. A failure mark says "this channel would not play". A healthy
// player whose OWN STASH says it is playing that channel is proof to the
// contrary, so the mark is dropped.
//
// Without this the mark outlives the failure, because the only other place
// that clears one runs when a play STARTS, not when one succeeds: a transient
// error during first load marked a channel, the stream then recovered, and the
// guide showed a channel the user was watching as "Failed HH:MM - Space to
// retry", with the alert glyph and WITHOUT the playing glyph, because the
// failure state displaces the playing state. Seen on the real display
// 2026-09-22 with mpv reporting h264 and 33.9 s of cache at the time.
//
// Only "agree" clears, and that is deliberately the strictest verdict
// reconcileVerdict gives: the player is up, on our source, and on the exact
// channel the guide names. "unknown" (stopping, nothing playing, or the
// player's record says playing false) and "diverged" both leave the mark
// alone, so a channel that really did fail keeps its mark.
function failedAfterHealthy(failed, verdictState, nowPlaying) {
  var src = failed && typeof failed === "object" ? failed : {}
  if (str(verdictState) !== "agree" || !nowPlaying) return src
  var id = str(nowPlaying.id)
  if (id === "" || src[id] === undefined) return src
  return withoutFailed(src, id)
}

function withoutFailed(failed, id) {
  var out = {}
  var src = failed && typeof failed === "object" ? failed : {}
  for (var k in src) if (k !== str(id)) out[k] = src[k]
  return out
}

// R13, the FileView's "landed". Whether the write the service last asked for
// is the one the FileView has just reported on. One `saved` per setText was
// measured for two back-to-back calls (2026-10-11) and does NOT hold for a
// burst: ten warm switches issued 20 setText and raised 14 `saved` on this
// tree, 15 on lane-key-s2 (a queued write replaced by a later one is dropped
// without a signal), so a counter of setText calls stays above zero for the
// rest of the session and every hold waits for ever -- and on lane-key-s2
// the same stuck counter made every foreign reload read as "save in flight"
// (D-SRC-15's sibling). Measured 2026-10-12 with a 26-write probe under
// cage: `text()` tracks the content of the write job that STARTED (after a
// burst of twenty it still read T19 while T20 was pending; a failed write
// reads its own content and then `saveFailed`), `textChanged` precedes each
// `saved`, and the last content asked for is always written last. So the
// write has landed exactly when the view's text IS the last text asked for;
// an earlier write's `saved` reads an earlier text and changes nothing.
function stateSaveLanded(viewText, askedText) {
  return str(viewText) === str(askedText) && str(askedText) !== ""
}

// R15. The reload counter counts BY REASON: one number per reason
// Model.reloadDisposition can answer, keyed by the reason string itself so
// the counter cannot name a reason the decision does not (rule 13: joined by
// a call, not by a name). Returns a NEW object, because a QML `property var`
// mutated in place raises no change signal. The harness reads it through
// pointerState as `stateReloadsByReason`; key-scenario's D3 asserts the
// `save-parked` count, which is the one the start-up chmod reload lands on,
// where the plain total was satisfied by the own-write echo that follows
// every start (round-3 review, lane B's P2).
function countReload(counts, reason) {
  var out = {}
  var src = counts && typeof counts === "object" ? counts : {}
  for (var k in src) if (Object.prototype.hasOwnProperty.call(src, k)) out[k] = Number(src[k]) || 0
  var r = str(reason)
  if (r === "") r = "unknown"
  out[r] = (out[r] || 0) + 1
  return out
}

// D-SRC-15 (R9). A reload of state.json NEVER replaces in-memory state that
// is newer than the file. The file is the service's own write target, so the
// in-memory state is newer whenever a save is parked behind the start-up dirs
// (`savePending`), a write is still in flight (`savesInFlight`: setText has
// returned, `saved` has not fired), or the last write FAILED (`saveFailed`:
// the file never caught up, and applying it would replay the loss). The one
// reload that must always apply is the FIRST (`loadedBefore` false): before
// it, memory is the empty default plus whatever stateOnLoad replays on top.
//
// The reload this exists for is not the service's own write echoed back
// (`ownWrite`, texts in recentSaves: skipped since R10 of the player design)
// but a touch by something else: the helper's start-up `state init` chmods
// the existing file, which is an inotify IN_ATTRIB and a `loaded` with the
// PRE-adoption text (measured 2026-10-11 on a FileView probe: a chmod from
// 0600 to 0600 reloads too). Applied, that text replaced the key and the
// record adoptActiveSource had just adopted, the parked save then wrote the
// key-less state and the entry flush stripped the URL: the user's active
// source lost on the first start after the upgrade (D-SRC-15). The sibling
// is the same flag: an IPC switch or remove before dirsReady (cacheReady
// comes first) parks a save, so the reload that follows is ignored too.
//
// D-SINK-19 round 14, R24a (D-SRC-22). "Ignored" was right for THAT reload
// and wrong for another: R9 said "the file is older than memory by
// construction, so an ignored reload loses nothing", which holds only while
// nothing but this service writes the file. A hand-run helper verb (`state
// source add`, `favorite add`) in the window -- a save parked at the start,
// in flight, or failed and not yet retried -- was ignored and then written
// over by the next save that landed, while the helper had answered ok:true
// (the round-13 data-loss lens, WF FAV WOK HADD FAV). 0.13.6 applied every
// reload and so lost the in-app change instead. Neither is acceptable,
// because one of them is always silent. So the question is now WHOSE text
// the reload carries, against the service's BASE (Service.landedState: the
// text it loaded, or its last save that LANDED, or the last foreign text it
// merged):
//   `matchesBase` (Model.sameState of the text and the base): the disk has
//                 not moved since the service last knew it -- the start-up
//                 chmod's pre-adoption text is exactly this -- so a held
//                 change still wins and the reload is ignored for the
//                 reason it is held, as R9 had it;
//   otherwise     the text is FOREIGN (neither the base nor one of our own
//                 writes): while a change is held it is MERGED
//                 (Model.mergeForeignState), never ignored and never applied
//                 blind; with nothing held it is applied as before, which is
//                 the merge with ours == base (pinned to agree).
//
//
// D-SINK-19 round 15, R25a (D-SRC-30). AN ECHO IS ONLY A TEXT STILL IN
// FLIGHT. `ownWrite` used to be "the text is one of the last eight this
// service wrote", and a backup the user had copied from the plugin's own
// file, put back after a later in-app change, carried one of those texts:
// it was ignored as an echo and the next save wrote over the restore,
// silently (the round-14 data-loss lens, FAV BAK DEL RSTB FAV). So
// Service.recentSaves now holds only the burst asked for since the last
// save that LANDED -- D-SRC-16's coalescing is why that can be more than one
// text -- and is cleared as a save lands. A text equal to an own save that
// landed and was then superseded is another writer's, and goes through the
// rest of this decision like any other foreign text. What that rests on is
// MEASURED (spikes/filewatch set r25, RESULT-2026-10-14-r25.txt): over 100
// bursts of the view's own saves, idle and loaded, all 85 echoes carried the
// text of the latest `saved` before them, none a text a later save had
// superseded, and none arrived while a later text was already asked. The echo of the save that just landed now arrives with
// nothing held and carries the base itself, so:
//   `matchesBase` and `memoryMatchesBase` with nothing held: the reload
//                 changes nothing -- the landed echo, a chmod, an identical
//                 rewrite -- and is ignored as `unchanged`, which is what
//                 the eight-text record used to do for the echo. With
//                 memory NOT the base (the no-write mode refused a change
//                 and a good copy was put back) it is applied, as before.
//
// -> { act: "apply" | "ignore" | "merge", reason }. Called by
// Service.applyUserState before anything else; an ignored reload runs
// neither reconcile nor the cache layout.
function reloadDisposition(ctx) {
  var c = ctx || {}
  if (c.loadedBefore !== true) return { act: "apply", reason: "first-load" }
  if (c.ownWrite === true) return { act: "ignore", reason: "own-write" }
  var held = c.savePending === true ? "save-parked"
    : (Number(c.savesInFlight) || 0) > 0 ? "save-in-flight"
    : c.saveFailed === true ? "save-failed" : ""
  if (held === "") {
    if (c.matchesBase === true && c.memoryMatchesBase === true) return { act: "ignore", reason: "unchanged" }
    return { act: "apply", reason: "file-newer" }
  }
  if (c.matchesBase === true) return { act: "ignore", reason: held }
  return { act: "merge", reason: "foreign-" + held }
}

// R24a. A value with its object keys sorted at every depth, so two states
// that differ only in key order serialize alike.
function sortedKeys(value) {
  if (Array.isArray(value)) return value.map(sortedKeys)
  if (!value || typeof value !== "object") return value
  var out = {}
  var keys = Object.keys(value).sort()
  for (var i = 0; i < keys.length; i++) out[keys[i]] = sortedKeys(value[keys[i]])
  return out
}

// R24a. A state (an object, or the text of a file) as a reader of the file
// would see it: through parseState, which is the service's own reader, then
// serialized with sorted keys. Two texts that parse to the same state are
// the same state whatever their bytes -- the helper writes compact JSON, the
// service indents it, and `state init` writes its own empty default where a
// fresh install's memory is parseState(""): R24c's identity, pinned.
function stateCanonical(state) {
  var text = typeof state === "string" ? state : JSON.stringify(state === undefined ? null : state)
  return JSON.stringify(sortedKeys(parseState(text)))
}

function sameState(a, b) {
  return stateCanonical(a) === stateCanonical(b)
}

function canonValue(v) {
  return JSON.stringify(sortedKeys(v === undefined ? null : v))
}

// One SET field merged three ways: theirs, minus what ours removed since the
// base, plus what ours added since the base, in theirs' order with ours'
// additions after. With ours equal to the base this IS theirs, element for
// element and in order (R24a's identity). `id` names an element.
function mergeSetField(base, ours, theirs, id) {
  var inBase = {}, inOurs = {}, inTheirs = {}, seen = {}
  var b = asList(base), o = asList(ours), t = asList(theirs)
  var i, k
  for (i = 0; i < b.length; i++) inBase[id(b[i])] = true
  for (i = 0; i < o.length; i++) inOurs[id(o[i])] = true
  for (i = 0; i < t.length; i++) inTheirs[id(t[i])] = true
  var out = []
  for (i = 0; i < t.length; i++) {
    k = id(t[i])
    if (seen[k] === true) continue
    if (inBase[k] === true && inOurs[k] !== true) continue   // ours removed it since the base
    seen[k] = true
    out.push(t[i])
  }
  for (i = 0; i < o.length; i++) {
    k = id(o[i])
    if (seen[k] === true || inBase[k] === true || inTheirs[k] === true) continue   // only ours' additions
    seen[k] = true
    out.push(o[i])
  }
  return out
}

// The names of the fields two records disagree on, sorted: what a conflict
// line names (never a value -- a source record carries a credentialed URL).
function recordFieldsDiffering(a, b) {
  var x = a && typeof a === "object" ? a : {}, y = b && typeof b === "object" ? b : {}
  var names = {}, k
  for (k in x) names[k] = true
  for (k in y) names[k] = true
  var out = []
  for (k in names) if (canonValue(x[k]) !== canonValue(y[k])) out.push(k)
  return out.sort()
}

// The scalars and the one list taken whole: theirs when theirs changed since
// the base, ours otherwise; both changed, and differently, is a conflict.
var MERGE_WHOLE_FIELDS = ["recents", "activeKey", "lastPlayed", "session", "cacheLayout"]

// D-SINK-19 round 14, R24a. THE three-way merge of a FOREIGN write into a
// session that holds a change the file does not (a save parked, in flight
// or failed). ONE pure function, every field rule here:
//   favorites, savedSearches, hiddenGroups  SETS, built on THEIRS: theirs'
//       elements in theirs' order, minus what ours removed since base, then
//       what ours added since base, in ours' order (mergeSetField; a saved
//       search is named by its folded terms, as parseState de-duplicates it).
//       The same SET as "ours, plus what theirs added, minus what theirs
//       removed"; the ORDER is theirs' (D-SRC-37: this comment used to say
//       the set was built on ours, which the code never did)
//   sources  RECORDS BY KEY: an add, a removal or a change made by theirs
//       since base is applied to ours, and ours' own adds, removals and
//       changes stand; a record BOTH changed (a change against a change, or
//       against a removal) is a conflict
//   recents, activeKey, lastPlayed, session, cacheLayout  theirs when theirs
//       changed since base and ours did not; ours when only ours did; both,
//       differently, is a conflict
//   entryMigrated  true if either side has it (the marker is never undone)
// A CONFLICT GOES TO THEIRS: the foreign write is the later act, and the
// in-app side of it was already told its save failed ("Could not write
// state.json") or has not been told it landed. Each is reported as
// { field, key } -- the key is a source's 8-hex key or "", never a URL -- and
// the caller logs one line per conflict.
// Every input is read through parseState, so a missing base is the empty
// state and every list is the shape the service holds; the result is read
// through it once more, so the de-duplication parseState applies to a file
// applies to the merge too.
// D-SINK-19 round 15, R25b (D-SRC-31): A MERGE NEVER DROPS SILENTLY. The
// caps used to be parseState's, applied to the result, and parseState stops
// at the cap: at 49 sources an in-app add and a hand-run `state source add`
// made 51, and the in-app record was cut with no line and no notice. The
// caps are applied HERE now, where it is known whose element is whose:
// theirs keeps its place (the later writer, as for a conflict -- and theirs
// alone is within every cap, it was read through parseState), so what goes
// past a cap is always ours' additions, at the tail. They are dropped and
// RETURNED -- `dropped.sources` the keys, `dropped.savedSearches` and
// `dropped.hiddenGroups` counts (a query and a group name are the user's or
// the provider's text, never logged) -- for Model.mergeDropLines (the
// journal, one line each) and Model.mergeDropNotice (the user, once).
// hiddenGroups is rule 15's sibling: the same shape at MAX_HIDDEN_GROUPS.
// -> { state, conflicts, dropped }
function mergeForeignState(base, ours, theirs) {
  var b = parseState(JSON.stringify(base || emptyState()))
  var o = parseState(JSON.stringify(ours || emptyState()))
  var t = parseState(JSON.stringify(theirs || emptyState()))
  var conflicts = []
  var out = cloneState(t)
  var dropped = { sources: [], savedSearches: 0, hiddenGroups: 0 }
  out.favorites = mergeSetField(b.favorites, o.favorites, t.favorites, function (x) { return str(x) })
  out.hiddenGroups = mergeSetField(b.hiddenGroups, o.hiddenGroups, t.hiddenGroups, function (x) { return str(x) })
  if (out.hiddenGroups.length > MAX_HIDDEN_GROUPS) {
    dropped.hiddenGroups = out.hiddenGroups.length - MAX_HIDDEN_GROUPS
    out.hiddenGroups = out.hiddenGroups.slice(0, MAX_HIDDEN_GROUPS)
  }
  out.savedSearches = mergeSetField(b.savedSearches, o.savedSearches, t.savedSearches,
                                    function (x) { return savedSearchTerms(x && x.query).join(" ") })
  if (out.savedSearches.length > MAX_SAVED_SEARCHES) {
    dropped.savedSearches = out.savedSearches.length - MAX_SAVED_SEARCHES
    out.savedSearches = out.savedSearches.slice(0, MAX_SAVED_SEARCHES)
  }
  var byKey = function (list) { var m = {}; for (var i = 0; i < list.length; i++) m[list[i].key] = list[i]; return m }
  var mb = byKey(b.sources), mo = byKey(o.sources), mt = byKey(t.sources)
  var sources = [], i, r, k
  for (i = 0; i < t.sources.length; i++) {
    r = t.sources[i]; k = r.key
    var rb = mb[k], ro = mo[k]
    var theirsChanged = !rb || canonValue(r) !== canonValue(rb)
    if (rb && !ro) {
      // ours removed it since the base
      if (theirsChanged) { conflicts.push({ field: "sources", key: k, fields: recordFieldsDiffering(rb, r) }); sources.push(r) }
      continue
    }
    if (ro) {
      var oursChanged = !rb || canonValue(ro) !== canonValue(rb)
      if (oursChanged && theirsChanged && canonValue(ro) !== canonValue(r)) {
        conflicts.push({ field: "sources", key: k, fields: recordFieldsDiffering(ro, r) })
        sources.push(r)
      } else if (oursChanged && !theirsChanged) sources.push(ro)
      else sources.push(r)
      continue
    }
    sources.push(r)   // theirs added it
  }
  for (i = 0; i < o.sources.length; i++) {
    r = o.sources[i]; k = r.key
    if (mt[k]) continue
    if (!mb[k]) { sources.push(r); continue }   // ours added it
    // theirs removed it since the base; ours changed it too: a conflict, theirs (the removal) wins
    if (canonValue(r) !== canonValue(mb[k])) conflicts.push({ field: "sources", key: k, fields: recordFieldsDiffering(mb[k], r) })
  }
  // Theirs' records were pushed first and number at most MAX_SOURCES, so
  // the records past the cap are ours' additions (R25b).
  for (i = MAX_SOURCES; i < sources.length; i++) dropped.sources.push(sources[i].key)
  out.sources = sources.slice(0, MAX_SOURCES)
  for (i = 0; i < MERGE_WHOLE_FIELDS.length; i++) {
    var f = MERGE_WHOLE_FIELDS[i]
    var cb = canonValue(b[f]), co = canonValue(o[f]), ct = canonValue(t[f])
    if (ct !== cb) {
      out[f] = t[f]
      if (co !== cb && co !== ct) conflicts.push({ field: f, key: "" })
    } else {
      out[f] = o[f]
    }
  }
  if (entryMigratedOf(o) || entryMigratedOf(t)) out.entryMigrated = true
  else delete out.entryMigrated
  return { state: parseState(JSON.stringify(out)), conflicts: conflicts, dropped: dropped }
}

var MERGE_LINE_HEAD = "state.json was changed by another program while a change made here was not yet saved; "

// The console line for one conflict: the field, the source key when it is a
// record, the names of the fields that differed -- never a value.
// D-SRC-36 (round 15): "kept the other program's VERSION OF ..."; the line
// used to read "kept the other program's the source <key>".
function mergeConflictLine(conflict) {
  var c = conflict || {}
  var what = str(c.field) === "sources" && isSourceKey(str(c.key))
    ? "the source " + str(c.key) + (asList(c.fields).length > 0 ? " (" + asList(c.fields).map(str).join(", ") + ")" : "")
    : str(c.field)
  return MERGE_LINE_HEAD + "kept the other program's version of " + what
}

function mergeDropCount(dropped) {
  var d = dropped || {}
  return { sources: asList(d.sources).filter(function (k) { return isSourceKey(str(k)) }).map(str),
           savedSearches: Math.max(0, Math.floor(Number(d.savedSearches) || 0)),
           hiddenGroups: Math.max(0, Math.floor(Number(d.hiddenGroups) || 0)) }
}

// R25b. The journal: one line per element a merge dropped at a cap -- a
// source by its key, a saved search or a hidden group as itself, never its
// text -- with the cap. [] when nothing was dropped.
function mergeDropLines(dropped) {
  var d = mergeDropCount(dropped)
  var out = [], i
  for (i = 0; i < d.sources.length; i++) {
    out.push(MERGE_LINE_HEAD + "the source " + d.sources[i] + " added here was not kept (the limit is " + MAX_SOURCES + " sources)")
  }
  for (i = 0; i < d.savedSearches; i++) {
    out.push(MERGE_LINE_HEAD + "a saved search made here was not kept (the limit is " + MAX_SAVED_SEARCHES + " saved searches)")
  }
  for (i = 0; i < d.hiddenGroups; i++) {
    out.push(MERGE_LINE_HEAD + "a group hidden here was not kept (the limit is " + MAX_HIDDEN_GROUPS + " hidden groups)")
  }
  return out
}

// R25b. What the user is told, ONCE per merge that dropped anything: how
// many of each, and the cap -- composed from counts and constants alone, so
// it carries no URL, no label, no query and no group name. null when nothing
// was dropped.
function mergeDropNotice(dropped) {
  var d = mergeDropCount(dropped)
  var parts = []
  var plural = function (n, one, many) { return n + " " + (n === 1 ? one : many) }
  if (d.sources.length > 0) parts.push(plural(d.sources.length, "source", "sources") + " added here (the limit is " + MAX_SOURCES + " sources)")
  if (d.savedSearches > 0) parts.push(plural(d.savedSearches, "saved search", "saved searches") + " made here (the limit is " + MAX_SAVED_SEARCHES + " saved searches)")
  if (d.hiddenGroups > 0) parts.push(plural(d.hiddenGroups, "hidden group", "hidden groups") + " made here (the limit is " + MAX_HIDDEN_GROUPS + " hidden groups)")
  if (parts.length === 0) return null
  var n = d.sources.length + d.savedSearches + d.hiddenGroups
  return { title: "Not every change was kept",
           body: "Another program changed state.json while a change made here was not yet saved, and together they went past a limit. "
                 + "The other program's version was kept, and " + parts.join(" and ") + (n === 1 ? " was" : " were")
                 + " not kept. Make room, then add " + (n === 1 ? "it" : "them") + " again." }
}
// ---- D-SINK-19 round 12, R22a: A STATE THAT DID NOT LOAD IS NEVER WRITTEN ----
//
// The round-11 data-loss lens (live, both host shapes): a migrated install
// whose state.json could not be read at the start had an empty state written
// over it -- every source, credential and favourite gone. stateFile's
// onLoadFailed used to call applyUserState(""), so a failed read was applied
// as an EMPTY state, the migration ran on it and marked it, its save parked
// behind the start-up dirs, the real text arriving with the helper's chmod
// was ignored because a save was parked (R9), and the parked save landed.
// The cache layout's save did the same through an unreadable state
// DIRECTORY on every tree since D-SINK-19 began, 0.13.6 included.
//
// What Quickshell's FileView reports, MEASURED on Quickshell 0.3.1 in a
// nested headless cage on 2026-10-13 (one FileView per case, the enum is
// qs::io::FileViewError in quickshell-io.qmltypes):
//   no file at the path                      loadFailed 2 FileNotFound
//   a file with mode 0000 (or 0200)          loadFailed 3 PermissionDenied
//   a directory where the file should be     loadFailed 4 NotAFile
//   a FIFO at the path                       loadFailed 4 NotAFile
//   the file inside a directory with 0000    loadFailed 2 FileNotFound  <-- !
//   the file inside a directory with 0600    loadFailed 2 FileNotFound  <-- !
//   a dangling symlink, a missing parent     loadFailed 2 FileNotFound
//   an empty file, a file of garbage         loaded (text "" / the garbage)
// So FileNotFound does NOT mean "the file does not exist": an unreadable
// directory reads exactly like a fresh install, and no later event says
// otherwise (the restored 0000 directory raised no fileChanged in that run;
// inotify_add_watch had failed with EACCES). The one party that can tell the
// two apart is the helper's start-up `state init`, which lstat()s the path
// before it changes anything and reports what it found (`found`), so a
// FileNotFound is a fresh install only when the helper says `absent` too.
//
// The numbers are FileViewError's, in its declaration order; the node suite
// reads the installed qmltypes and fails if the order moves (rule 13: a join
// by number is checked).
var STATE_LOAD_ERRORS = { 1: "io-error", 2: "absent", 3: "permission", 4: "not-a-file" }

// One load outcome -> what it IS. `result` is { loaded: true, text } from
// onLoaded, or { loaded: false, error } from onLoadFailed. "loaded" means the
// text parses as a state (a JSON object; parseState reads anything that
// does); "unparsed" is a file that was read and is not one -- an empty file
// included, since nothing this plugin writes is empty. Any error number this
// table does not know is an I/O error: never "absent" by default.
function stateLoadKind(result) {
  var r = result || {}
  if (r.loaded !== true) {
    var e = Math.floor(Number(r.error))
    return STATE_LOAD_ERRORS[e] || "io-error"
  }
  return parseJsonObject(r.text) ? "loaded" : "unparsed"
}

// The helper's `state init` reply -> "absent" when it found nothing at the
// path before it created the file, "present" when it found anything at all
// (a file, a directory, something it could not lstat), and "unknown" when
// there is no reply to read: the init failed, printed nothing, or is a build
// that predates the field. Only "absent" can make a fresh install.
// R23c (round 13): `timedOut` -- the service's watchdog killed the init --
// answers "timeout", whatever the killed process printed or exited with.
// R24b (round 14): two kinds of "present" carry their own answer, because
// the FileView reports both as FileNotFound and the sentence that fixes
// each is not the folder-permission one: "link", a symbolic link at the
// path whose target is missing or not a regular file (the helper refuses to
// read or write through it), and "not-a-dir", something that is not a
// directory where the state DIRECTORY (or a folder above it) should be.
function stateInitFound(text, exitCode, timedOut) {
  if (timedOut === true) return "timeout"
  if (Number(exitCode) !== 0) return "unknown"
  var lines = str(text).split("\n")
  for (var i = lines.length - 1; i >= 0; i--) {
    var o = parseJsonObject(lines[i])
    if (!o || o.kind !== "state" || o.action !== "init") continue
    var f = str(o.found)
    if (f === "absent") return "absent"
    // R25c: "folder-link", a link at the state FOLDER (or above it) that
    // leads nowhere, is the helper's word too and gets its own sentence.
    if (f === "link" || f === "not-a-dir" || f === "folder-link") return f
    if (f === "file" || f === "other" || f === "unreadable") return "present"
    return "unknown"
  }
  return "unknown"
}

// What the service does with a load that is not "loaded".
//   ctx.kind         Model.stateLoadKind of the latest load
//   ctx.loadedBefore a state has been applied this session
//   ctx.initFound    Model.stateInitFound, "" until the start-up init exits
//   ctx.retried      the one re-read after the init has been spent
// -> { act, reason }
//   apply  the load is a state: apply it (and lift any no-write mode)
//   fresh  nothing exists at the path: an empty state, the migration may run
//   wait   the start-up init has not answered; nothing is applied or written
//   retry  re-read once: the init restores the modes of the directory and
//          file it finds, so the file may be readable now (it is, for both
//          chmod 0000 cases; a 0000 file also raises its own reload)
//   block  no-write mode for the session: every state write is refused, the
//          migration does not run, the entry is left as it is
// Mid-session (`loadedBefore`) any load that is not a state blocks at once
// and memory stands: a reload never replaces memory with a state that did
// not load, and a vanished file is not a fresh install while the session
// that read it is still running (the unreadable directory reads the same).
function stateLoadDecision(ctx) {
  var c = ctx || {}
  var kind = str(c.kind)
  if (kind === "loaded") return { act: "apply", reason: "loaded" }
  if (kind === "") return { act: "wait", reason: "no-load" }
  if (c.loadedBefore === true) return { act: "block", reason: kind }
  var found = str(c.initFound)
  if (found === "") return { act: "wait", reason: "init" }
  // R23c: the init never answered (the service's watchdog killed it), so
  // there is no witness and nothing a re-read could fix: the load that was
  // waiting on it decides as the no-write mode, with that reason.
  if (found === "timeout") return { act: "block", reason: "init-timeout" }
  if (kind === "absent" && found === "absent") return { act: "fresh", reason: "absent" }
  if (c.retried !== true) return { act: "retry", reason: kind }
  // R24b: the helper named what is at the path, and that is the reason --
  // the folder-permission sentence "absent-unconfirmed" carries would send
  // the user to chmod a folder that is fine.
  if (found === "link" || found === "not-a-dir" || found === "folder-link") return { act: "block", reason: found }
  return { act: "block", reason: kind === "absent" && found !== "unknown" ? "absent-unconfirmed" : kind }
}

// The one gate every state write goes through (Service.saveState).
//   blocked  the no-write mode's reason, "" when writes are allowed
//   loaded   a state has been applied this session
//   dirsReady the start-up `state init` has exited
// -> "refuse" | "park" | "write". A save asked for before any state has
// loaded PARKS (the section-15 replay: a play recorded before the load is
// written once the file it merges onto is known), never writes: before
// R22a a save made with the dirs ready and the load still out wrote the
// empty default over the file.
function stateWriteGate(ctx) {
  var c = ctx || {}
  if (str(c.blocked) !== "") return "refuse"
  if (c.loaded !== true || c.dirsReady !== true) return "park"
  return "write"
}

